<script setup>import {reactive,ref} from 'vue';import {state,actions} from '../../domain/prototypeStore.js';const form=reactive({title:'',group:'现场处置组',deadline:'30分钟',eventId:''}),msg=ref('');const add=()=>{const r=actions.createTask(form);msg.value=r.message||(r.ok?'已创建临时任务':'操作失败')}</script>
<template><section class="page-stack"><div class="page-heading"><div class="module-icon">任</div><div><h2>应急任务</h2><p>下达临时任务、催办并查看处理反馈</p></div></div><article class="panel"><div class="button-row"><input v-model="form.title" placeholder="临时任务名称"><select v-model="form.group"><option>现场处置组</option><option>安全保障组</option><option>物资保障组</option></select><input v-model="form.deadline" placeholder="时限"><button class="primary-button active" @click="add">创建任务</button></div></article><p v-if="msg" class="action-message">{{msg}}</p><div class="table-card"><table><thead><tr><th>任务</th><th>责任组</th><th>时限</th><th>状态</th><th>反馈</th><th>操作</th></tr></thead><tbody><tr v-for="t in state.tasks" :key="t.id"><td>{{t.title}}<small>{{t.id}}</small></td><td>{{t.assignee}}</td><td>{{t.deadline}}</td><td>{{t.status}}</td><td>{{t.feedback||'暂无'}}</td><td><button class="secondary-button" @click="actions.remindTask(t.id)">催办 {{t.reminders||0}}</button></td></tr></tbody></table></div></section></template>
